/** The countries Wasel runs stores in, each with its own currency and clock. */
export const REGIONS: Region[] = [
  { country: 'IQ', currency: 'IQD', decimals: 0, timeZone: 'Asia/Baghdad', center: { lat: 33.3152, lng: 44.3661 } },
  { country: 'SA', currency: 'SAR', decimals: 2, timeZone: 'Asia/Riyadh', center: { lat: 24.7136, lng: 46.6753 } },
  { country: 'AE', currency: 'AED', decimals: 2, timeZone: 'Asia/Dubai', center: { lat: 25.2048, lng: 55.2708 } },
  { country: 'KW', currency: 'KWD', decimals: 3, timeZone: 'Asia/Kuwait', center: { lat: 29.3759, lng: 47.9774 } },
  { country: 'QA', currency: 'QAR', decimals: 2, timeZone: 'Asia/Qatar', center: { lat: 25.2854, lng: 51.531 } },
  { country: 'BH', currency: 'BHD', decimals: 3, timeZone: 'Asia/Bahrain', center: { lat: 26.2285, lng: 50.586 } },
  { country: 'OM', currency: 'OMR', decimals: 3, timeZone: 'Asia/Muscat', center: { lat: 23.588, lng: 58.3829 } },
]

export const country = (code: string) => COUNTRIES.find((c) => c.code === code)
export const region = (code: string) => REGIONS.find((r) => r.country === code) ?? REGIONS[0]
export const regionForCurrency = (currency: string) => REGIONS.find((r) => r.currency === currency) ?? REGIONS[0]

/** A flag emoji from the two-letter code. */
export function flag(code: string) {
  return String.fromCodePoint(...[...code.toUpperCase()].map((c) => 0x1f1e6 + c.charCodeAt(0) - 65))
}
